    (4, 24, "| | ሚስቱ ረክላ ሳለች ባትረክስም በባሏ. ላይ የቃቅንልት መንፈስ ቢነሣበትና በሚስቱ ቢቀና ያ ሰው ሚስቱን ወዶ ህን ያምጣት።"),
